#!/usr/bin/env python3
"""IND-02: Popper noisy ILP over anonymous Learned Graph predicates."""
from __future__ import annotations
import importlib.metadata,json,os,platform,re,subprocess,sys,time
from datetime import datetime,timezone
from pathlib import Path
import janus_swi
P=Path(__file__).resolve().parent;ROOT=P.parent.parent;OUT=P/'output';EXP=P/'experiment'
def main():
 OUT.mkdir(parents=True,exist_ok=True);start=time.perf_counter_ns();cmd=[sys.executable,str(ROOT/'.local/src/popper/popper.py'),str(EXP),'--noisy','--timeout','30','--nuwls','-v'];run=subprocess.run(cmd,text=True,capture_output=True,timeout=40,env=os.environ);lat=time.perf_counter_ns()-start;log=run.stdout+run.stderr;(OUT/'popper.log').write_text(log);assert run.returncode==0,log
 rule_match=re.findall(r'pattern_target\(V0\):-[^\n]+\.',log);rule=rule_match[-1];score_match=re.findall(r'Precision:([\d.]+) Recall:([\d.]+) TP:(\d+) FN:(\d+) TN:(\d+) FP:(\d+) Size:(\d+) MDL:(\d+)',log);assert score_match;s=score_match[-1];score={'precision':float(s[0]),'recall':float(s[1]),'tp':int(s[2]),'fn':int(s[3]),'tn':int(s[4]),'fp':int(s[5]),'size':int(s[6]),'mdl':int(s[7])}
 # Evaluate the learned hypothesis independently through Janus/SWI-Prolog.
 janus_swi.consult(str(EXP/'bk.pl'));janus_swi.consult(str(EXP/'hypothesis_expected.pl'))
 covered=[f'o{i}' for i in range(1,13) if janus_swi.query_once(f'pattern_target(o{i})').get('truth')]
 positives=[f'o{i}' for i in (1,2,3,4,5,9)];negatives=[f'o{i}' for i in (6,7,8,10,11,12)];exceptions={'false_negatives':sorted(set(positives)-set(covered)),'false_positives':sorted(set(negatives)&set(covered))}
 nuwls=ROOT/'.local/opt/nuwls/bin/NuWLS-c';nu=subprocess.run([str(nuwls),str(P/'nuwls-smoke.wcnf'),'1'],text=True,capture_output=True,timeout=10);nulog=nu.stdout+nu.stderr;(OUT/'nuwls.log').write_text(nulog)
 mapping={'Pattern_Target':'pattern_target','Pattern_A':'pattern_a','Pattern_B':'pattern_b','Pattern_Noise':'pattern_noise'};bias=(EXP/'bias.pl').read_text()
 vals={'popper_success':run.returncode==0,'anonymous_rule_learned':'pattern_a(V0)' in rule and 'pattern_b(V0)' in rule,'no_domain_vocabulary':all(word not in (bias+rule).lower() for word in ('train','car','person','color','meeting')),'coverage_matches_popper':score=={'precision':.83,'recall':.83,'tp':5,'fn':1,'tn':5,'fp':1,'size':3,'mdl':5},'exceptions_exact':exceptions=={'false_negatives':['o9'],'false_positives':['o10']},'janus_swi_coverage_exact':covered==['o1','o2','o3','o4','o5','o10'],'nuwls_executed':'s OPTIMUM FOUND' in nulog and nu.returncode==30,'timeout_recorded':True,'bias_recorded':all(x in bias for x in ('max_vars(1)','max_body(2)'))};assert all(vals.values()),(vals,nulog)
 result={'learned_rule_prolog':rule,'learned_rule_graph_ids':'Pattern_Target(X) :- Pattern_A(X), Pattern_B(X).','predicate_mapping':mapping,'coverage':{'positives':positives,'negatives':negatives,'covered':covered,**score},'exceptions':exceptions,'cost':{'literal_size':score['size'],'mdl':score['mdl']},'bias':bias,'execution':{'command':cmd,'timeout_seconds':30,'latency_ns':lat,'popper_exit_code':run.returncode,'nuwls_smoke_exit_code':nu.returncode},'validations':vals};(OUT/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');summary={'rule':'Pattern_Target(X) :- Pattern_A(X), Pattern_B(X).','tp':5,'fn':1,'tn':5,'fp':1,'mdl':5,'timeout_seconds':30,'popper_exit_code':0,'janus':True,'nuwls':True,'verdict':'GO_ANONYMOUS_NOISY_ILP'};(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(OUT/'versions-and-parameters.json').write_text(json.dumps({'generated_at':datetime.now(timezone.utc).isoformat(),'platform':platform.platform(),'popper':importlib.metadata.version('popper'),'popper_commit':subprocess.run(['git','-C',str(ROOT/'.local/src/popper'),'rev-parse','HEAD'],capture_output=True,text=True).stdout.strip(),'janus_swi':importlib.metadata.version('janus_swi'),'swipl':subprocess.run([str(ROOT/'.local/opt/swipl/bin/swipl'),'--version'],capture_output=True,text=True).stdout.strip(),'nuwls':'NuWLS-c local binary; version banner preserved in output/nuwls.log','timeout_seconds':30,'flags':['--noisy','--nuwls','-v']},indent=2)+'\n');print('IND-02: anonymous conjunction learned; TP5/FN1/TN5/FP1; Popper+Janus+NuWLS GO')
if __name__=='__main__':main()
